python.code:
seen = set()
for value in [4, 7, 4]:
    if value in seen:
        print("repeat", value)
        break
    seen.add(value)

java.code:
Set<Integer> seen = new HashSet<>();
for (int value : List.of(4, 7, 4)) {
    if (seen.contains(value)) {
        System.out.println("repeat " + value);
        break;
    }
    seen.add(value);
}

javascript.code:
const seen = new Set();
for (const value of [4, 7, 4]) {
  if (seen.has(value)) {
    console.log("repeat", value);
    break;
  }
  seen.add(value);
}

cpp.code:
#include <iostream>
#include <unordered_set>
#include <vector>

std::unordered_set<long long> seen;
for (long long value : std::vector<long long>{4, 7, 4}) {
    if (seen.count(value)) {
        std::cout << "repeat " << value << "\n";
        break;
    }
    seen.insert(value);
}

python.code:
