java.code:
Map<Character, Integer> counts = new HashMap<>();
for (char ch : "banana".toCharArray()) {
    counts.put(ch, counts.getOrDefault(ch, 0) + 1);
}
System.out.println(counts.get('a'));

javascript.code:
const counts = new Map();
for (const ch of "banana") {
  counts.set(ch, (counts.get(ch) ?? 0) + 1);
}
console.log(counts.get("a"));

cpp.code:
#include <iostream>
#include <unordered_map>
#include <string>

std::unordered_map<char, long long> counts;
for (char ch : std::string("banana")) {
    counts[ch] += 1;
}
std::cout << counts['a'] << "\n";
